-- 只读；完整约束/函数体需对照受审文件，异常计数全零，不能只看对象存在。
SELECT table_name,ordinal_position,column_name,data_type,udt_schema,udt_name,character_maximum_length,numeric_precision,numeric_scale,datetime_precision,is_nullable,column_default,collation_name,is_identity,identity_generation,is_generated,generation_expression FROM information_schema.columns WHERE table_schema=current_schema() AND table_name IN ('agent_memory_thread_execution','agent_memory_thread_member','agent_memory_thread_namespace','agent_memory_thread_resume') ORDER BY table_name,ordinal_position;
SELECT c.relname,k.conname,k.contype,pg_get_constraintdef(k.oid) AS definition FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema() AND c.relname IN ('agent_memory_thread_execution','agent_memory_thread_member','agent_memory_thread_namespace','agent_memory_thread_resume') ORDER BY c.relname,k.conname;
SELECT tablename,indexname,indexdef FROM pg_indexes WHERE schemaname=current_schema() AND tablename IN ('agent_memory_thread_execution','agent_memory_thread_member','agent_memory_thread_namespace','agent_memory_thread_resume') ORDER BY tablename,indexname;
SELECT c.relname,t.tgname,pg_get_triggerdef(t.oid) AS definition,pg_get_functiondef(t.tgfoid) AS function_definition FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname=current_schema() AND c.relname IN ('agent_memory_thread_execution','agent_memory_thread_resume') AND NOT t.tgisinternal ORDER BY c.relname,t.tgname;
SELECT count(*) AS invalid_counter FROM agent_memory_thread_execution WHERE refresh_count NOT BETWEEN 0 AND 3;
SELECT count(*) AS mismatched_pending FROM agent_memory_thread_execution e LEFT JOIN agent_memory_thread_resume r ON r.tenant_id=e.tenant_id AND r.execution_id=e.execution_id AND r.record_kind='RESUME' AND r.candidate_id=e.pending_resume_request_id WHERE e.state='REFRESH_PENDING' AND (r.candidate_id IS NULL OR r.candidate_phase<>'PENDING' OR r.refresh_count<>e.refresh_count OR r.candidate_digest<>e.pending_candidate_digest);
SELECT count(*) AS invalid_none_members FROM agent_memory_thread_execution e JOIN agent_memory_thread_member m USING(tenant_id,execution_id) WHERE e.checkpoint_mode='NONE';
SELECT count(*) AS invalid_successor FROM agent_memory_thread_resume WHERE next_wait_event_id IS NOT NULL AND (candidate_phase<>'APPLIED_EXPIRED' OR next_wait_event_id=wait_event_id OR refresh_count>=3 OR receipt_state<>'WAITING_CONTEXT' OR dispatch_allowed);
SELECT state,refresh_count,count(*) AS row_count FROM agent_memory_thread_execution GROUP BY state,refresh_count;
